import backtrader as bt


class QCBStrategy(bt.Strategy):

    ENTRY_LEVEL = 179.33
    TP1_LEVEL = 184.89
    TP2_LEVEL = 192.95
    RISK_PCT = 0.02

    def __init__(self):
        self.ema8 = bt.indicators.EMA(self.data.close, period=8)
        self.order = None
        self.tp1_done = False
        self.trailing_stop_level = None
        self.entry_size = 0

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            if order is self.order:
                self.order = None
                if order.status == order.Completed and order.isbuy():
                    self.entry_size = order.executed.size

    def next(self):
        if self.order:
            return

        if not self.position:
            self.tp1_done = False
            self.trailing_stop_level = None

            if self.data.close[0] > self.ENTRY_LEVEL:
                entry_price = self.data.close[0]
                initial_stop = self.ema8[0]
                risk_per_share = entry_price - initial_stop

                if risk_per_share <= 0:
                    return

                portfolio_value = self.broker.getvalue()
                risk_amount = portfolio_value * self.RISK_PCT
                size = int(risk_amount / risk_per_share)

                if size <= 0:
                    return

                self.trailing_stop_level = initial_stop
                self.order = self.buy(size=size)

        else:
            # Advance trailing stop to current EMA level but never retreat
            self.trailing_stop_level = max(self.trailing_stop_level, self.ema8[0])
            close = self.data.close[0]

            # Final take-profit: close the remaining position
            if self.tp1_done and close >= self.TP2_LEVEL:
                self.order = self.close()
                return

            # Take-profit 1: close 50% of original entry size
            if not self.tp1_done and close >= self.TP1_LEVEL:
                tp1_size = self.entry_size // 2
                if tp1_size > 0:
                    self.order = self.sell(size=tp1_size)
                self.tp1_done = True
                return

            # Trailing stop: close entire remaining position
            if close <= self.trailing_stop_level:
                self.order = self.close()
